// shared event emitter
type Events = {
  'user.created': { id: string };
  'order.paid': { orderId: string; cents: number };
};

function emit<E extends keyof Events, P = any>(event: E, payload: P): void {
  bus.publish(event, payload);
}

// usage
emit('order.paid', { orderId: 'o1' }); // missing cents — no error
emit('user.created', 'whoops');        // wrong payload type — no error
